{
  "iteration": 1,
  "pcvs": [
    {
      "name": "temporal_chunks",
      "expression": "1 + (x.shape[2] - 1) // 4",
      "rationale": "Tracks encoder invocations and per-chunk Python, dispatch, and cache-management overhead."
    },
    {
      "name": "spatial_area",
      "expression": "x.shape[0] * x.shape[3] * x.shape[4]",
      "rationale": "Captures spatial work specific to the initial single-frame chunk and fixed spatial costs."
    },
    {
      "name": "chunk_spatial_work",
      "expression": "x.shape[0] * (1 + (x.shape[2] - 1) // 4) * x.shape[3] * x.shape[4]",
      "rationale": "Models convolution, normalization, activation, and copying work across temporal chunks."
    },
    {
      "name": "attention_pair_work",
      "expression": "x.shape[0] * (1 + (x.shape[2] - 1) // 4) * ((x.shape[3] // 8) * (x.shape[4] // 8)) ** 2",
      "rationale": "Models quadratic spatial attention work at the encoder's compressed resolution."
    }
  ],
  "hypothesis": "Instruction count is approximately a combination of per-chunk overhead, spatial work with distinct initial and subsequent chunk costs, and quadratic attention work."
}
